package com.example.editor.definition.runtime.session;

import java.nio.file.Path;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;

@Component
@ConfigurationProperties(prefix = "dsl.editors.runtime.sessions")
public class EditorSessionProperties {
    private boolean enabled = true;
    private Path directory = Path.of("./data/editor-sessions");
    private String fileSuffix = ".editor-session.json";
    private boolean useEtag = true;
    private String diagramFileSuffix = ".editor-session-diagram.json";
    private int maximumHistoryEntries = 50;
    private int maximumHistorySessionsInMemory = 8;
    private int maximumWorkingCopiesInMemory = 16;
    private int maximumPendingEventsInMemory = 256;
    private int maximumPendingEventSessions = 16;
    private int maximumPendingEventFallbackEvents = 512;
    private long maximumPendingEventSpoolBytesPerSession = 16L * 1024L * 1024L;
    private Path pendingEventSpoolDirectory;
    /** Descripción: Evalúa la condición «isEnabled» sin modificar el estado externo. Entradas: no requiere parámetros de entrada. Salida: devuelve un indicador que expresa el resultado de la condición. */ public boolean isEnabled() { return enabled; }
    /** Descripción: Actualiza el estado gestionado por EditorSessionProperties mediante la operación «setEnabled». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setEnabled(boolean value) { enabled = value; }
    /** Descripción: Obtiene la información correspondiente a «getDirectory» dentro de EditorSessionProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public Path getDirectory() { return directory; }
    /** Descripción: Actualiza el estado gestionado por EditorSessionProperties mediante la operación «setDirectory». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setDirectory(Path value) { directory = value; }
    /** Descripción: Obtiene la información correspondiente a «getFileSuffix» dentro de EditorSessionProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public String getFileSuffix() { return fileSuffix; }
    /** Descripción: Actualiza el estado gestionado por EditorSessionProperties mediante la operación «setFileSuffix». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setFileSuffix(String value) { fileSuffix = value; }
    /** Descripción: Obtiene la información correspondiente a «getDiagramFileSuffix» dentro de EditorSessionProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public String getDiagramFileSuffix() { return diagramFileSuffix; }
    /** Descripción: Actualiza el estado gestionado por EditorSessionProperties mediante la operación «setDiagramFileSuffix». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setDiagramFileSuffix(String value) { diagramFileSuffix = value; }
    /** Descripción: Evalúa la condición «isUseEtag» sin modificar el estado externo. Entradas: no requiere parámetros de entrada. Salida: devuelve un indicador que expresa el resultado de la condición. */ public boolean isUseEtag() { return useEtag; }
    /** Descripción: Actualiza el estado gestionado por EditorSessionProperties mediante la operación «setUseEtag». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setUseEtag(boolean value) { useEtag = value; }
    /** Descripción: Obtiene la información correspondiente a «getMaximumHistoryEntries» dentro de EditorSessionProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getMaximumHistoryEntries() { return maximumHistoryEntries; }
    /** Descripción: Actualiza el estado gestionado por EditorSessionProperties mediante la operación «setMaximumHistoryEntries». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaximumHistoryEntries(int value) { maximumHistoryEntries = Math.max(1, value); }
    /** Descripción: Obtiene la información correspondiente a «getMaximumHistorySessionsInMemory» dentro de EditorSessionProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getMaximumHistorySessionsInMemory() { return maximumHistorySessionsInMemory; }
    /** Descripción: Actualiza el estado gestionado por EditorSessionProperties mediante la operación «setMaximumHistorySessionsInMemory». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaximumHistorySessionsInMemory(int value) { maximumHistorySessionsInMemory = Math.max(1, value); }
    /** Descripción: Obtiene la información correspondiente a «getMaximumWorkingCopiesInMemory» dentro de EditorSessionProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getMaximumWorkingCopiesInMemory() { return maximumWorkingCopiesInMemory; }
    /** Descripción: Actualiza el estado gestionado por EditorSessionProperties mediante la operación «setMaximumWorkingCopiesInMemory». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaximumWorkingCopiesInMemory(int value) { maximumWorkingCopiesInMemory = Math.max(1, value); }
    /** Descripción: Obtiene la información correspondiente a «getMaximumPendingEventsInMemory» dentro de EditorSessionProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getMaximumPendingEventsInMemory() { return maximumPendingEventsInMemory; }
    /** Descripción: Actualiza el estado gestionado por EditorSessionProperties mediante la operación «setMaximumPendingEventsInMemory». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaximumPendingEventsInMemory(int value) { maximumPendingEventsInMemory = Math.max(1, value); }
    /** Descripción: Obtiene la información correspondiente a «getMaximumPendingEventSessions» dentro de EditorSessionProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getMaximumPendingEventSessions() { return maximumPendingEventSessions; }
    /** Descripción: Actualiza el estado gestionado por EditorSessionProperties mediante la operación «setMaximumPendingEventSessions». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaximumPendingEventSessions(int value) { maximumPendingEventSessions = Math.max(1, value); }
    /** Descripción: Obtiene la información correspondiente a «getMaximumPendingEventFallbackEvents» dentro de EditorSessionProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getMaximumPendingEventFallbackEvents() { return maximumPendingEventFallbackEvents; }
    /** Descripción: Actualiza el estado gestionado por EditorSessionProperties mediante la operación «setMaximumPendingEventFallbackEvents». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaximumPendingEventFallbackEvents(int value) { maximumPendingEventFallbackEvents = Math.max(1, value); }
    /** Descripción: Obtiene la información correspondiente a «getMaximumPendingEventSpoolBytesPerSession» dentro de EditorSessionProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public long getMaximumPendingEventSpoolBytesPerSession() { return maximumPendingEventSpoolBytesPerSession; }
    /** Descripción: Actualiza el estado gestionado por EditorSessionProperties mediante la operación «setMaximumPendingEventSpoolBytesPerSession». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaximumPendingEventSpoolBytesPerSession(long value) { maximumPendingEventSpoolBytesPerSession = Math.max(1024L, value); }
    /** Descripción: Obtiene la información correspondiente a «getPendingEventSpoolDirectory» dentro de EditorSessionProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public Path getPendingEventSpoolDirectory() { return pendingEventSpoolDirectory == null ? directory.resolve(".pending-events") : pendingEventSpoolDirectory; }
    /** Descripción: Actualiza el estado gestionado por EditorSessionProperties mediante la operación «setPendingEventSpoolDirectory». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setPendingEventSpoolDirectory(Path value) { pendingEventSpoolDirectory = value; }
}
